        myConsoleLog('tabDati ' + tabDati );

}

/**
 * createCSV: converte la tabella idTabella in csv per metterla in idContent
 */
function createCSV(idTabella, idContent) {
    myConsoleLog('createCSV ' + idTabella + ' ' + idContent);

    const table = document.getElementById(idTabella);


    var titoliCsv = '';
    var nColonne = 0;
    // titoli delle colonne
    for (var j = 0, col; col = table.rows[0].cells[j]; j++) {
        const inner = col.innerHTML.replaceAll('<br>', ' ');
        let aggiungi = true;
        if ( inner.indexOf("aria") >= 0) {
            aggiungi = false;
            titoliCsv += inner + ' min;' + inner + ' med;' + inner + ' max;';
            nColonne += 3;
        }
        if ( inner.indexOf("Umidit") >= 0) {
            aggiungi = false;
            titoliCsv += inner + ' min;' + inner + ' max;';
            nColonne += 2;
        }
        if ( inner.indexOf("Vento") >= 0) {
            aggiungi = false;
            titoliCsv += inner + ' velocità;' + inner + ' raffica ora;' + inner + ' raffica m/s;' + inner + ' direz;';
            nColonne += 4;
        }
        if ( inner.indexOf("idrometric") >= 0) {
            aggiungi = false;
            titoliCsv += inner + ' min;' + inner + ' med;' + inner + ' max;';
            nColonne += 3;
        }
        if ( inner.indexOf("suolo") >= 0) {
            aggiungi = false;
            titoliCsv += inner + ' a 0cm;' + inner + ' a -10cm;' + inner + ' a -20cm;' + inner + ' a -30cm;';
            nColonne += 4;
        }

        if (aggiungi) {
            titoliCsv += inner + ';';
            nColonne += 1;
        }

    }
    // togliere l'ultimo ; e mettere a \n
    titoliCsv = titoliCsv.substring(0, titoliCsv.length-1) + '\n';

    var righeCsv = '';

    for (var i = 0, row; row = table.rows[i]; i++) {
        //iterate through rows
        //rows would be accessed using the "row" variable assigned in the for loop
        // salto tutte le righe che non hanno il numero di colonne previste
        if (row.cells.length != nColonne ) {
            continue;
        }

        for (var j = 0, col; col = row.cells[j]; j++) {
            //iterate through columns
            //columns would be accessed using the "col" variable assigned in the for loop
            var inner = col.innerHTML.replaceAll('<br>', ' ');
            inner = col.innerHTML.replaceAll('&gt;', '>');
            const separatore = ( ( j == row.cells.length-1 ) ? '\n' : ';');
            righeCsv += inner + separatore;
        }  
    }

    const tutta = titoliCsv + righeCsv;

    // per salvare in formato excel https://stackoverflow.com/questions/19492846/javascript-to-csv-export-encoding-issue
    // You should add the UTF-8 BOM at the start of the text, like:
    var element = document.createElement('a');
    element.setAttribute('href', 'data:text/csv;charset=UTF-8,%EF%BB%BF' + encodeURI(tutta));
    element.setAttribute('download', nomeStazione + '.csv');
    element.innerHTML = 'Dati della stazione in formato CSV';
    document.getElementById(idContent).append(element);

/*
    var pre = document.createElement("pre");
    pre.textContent = tutta;
    document.getElementById(idContent).append(pre);
*/

}

